contracts/Libraries/FullMath.sol.content:
pragma solidity ^0.8.25;

library FullMath {
    function mulDiv(uint256 a, uint256 b, uint256 denominator) internal pure returns (uint256 result) {
        uint256 prod0;
        uint256 prod1;
        assembly {
            let mm := mulmod(a, b, not(0))
            prod0 := mul(a, b)
            prod1 := sub(sub(mm, prod0), lt(mm, prod0))
        }

        if (prod1 == 0) {
            require(denominator > 0, "FullMath: denominator is zero");
            assembly {
                result := div(prod0, denominator)
            }
            return result;
        }

        require(denominator > prod1, "FullMath: result overflows uint256");

        uint256 remainder;
        assembly {
            remainder := mulmod(a, b, denominator)
            prod1 := sub(prod1, gt(remainder, prod0))
            prod0 := sub(prod0, remainder)
        }

        uint256 twos = denominator & (~denominator + 1);
        assembly {
            denominator := div(denominator, twos)
            prod0 := div(prod0, twos)
            twos := add(div(sub(0, twos), twos), 1)
        }

        unchecked {
            prod0 |= prod1 * twos;
        }

        unchecked {
            uint256 inverse = (3 * denominator) ^ 2;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;

            result = prod0 * inverse;
        }
        return result;
    }
}

contracts/Sentinels/BStockPauseSentinel..content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

import { EnumerableSetUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/structs/EnumerableSetUpgradeable.sol";
import { AccessControlledV8 } from "@venusprotocol/governance-contracts/contracts/Governance/AccessControlledV8.sol";
import { IEBrake } from "../EmergencyBrake/IEBrake.sol";
import { IBStockToken } from "../Interfaces/IBStockToken.sol";
import { ICompliance } from "../Interfaces/ICompliance.sol";
import { IPauseManager } from "../Interfaces/IPauseManager.sol";
import { IVToken } from "../Interfaces/IVToken.sol";

/**
 * @title BStockPauseSentinel
 * @author Venus
 * @notice Keeper-driven sentinel that zeroes the collateral factor (CF) of monitored bStock (tokenized equity)
 *         markets through EBrake while the issuer's PauseManager reports the token as paused, or the token's
 *         compliance module sanctions or blocklists the market.
 * @dev A paused bStock cannot be transferred. Liquidations still seize its vTokens, but no one can redeem them
 *      for the bStock until the pause ends, so liquidators cannot exit. Zeroing CF stops new debt against the
 *      collateral, while the liquidation threshold (LT) is left unchanged so existing positions are not pushed
 *      into liquidation.
 *      - Any market EBrake can act on: EBrake acts on the market's own comptroller and checks the listing there.
 *      - The pause is read from the PauseManager the token itself points to (pauseManager()), which is the
 *        one the token checks before every transfer.
 *      - A sanctioned or blocklisted vToken can neither send nor receive the token, which blocks redeems and
 *        mints just like a pause, so it is treated as one. The block is read from the compliance module the
 *        token itself points to (compliance()); a failing read counts as blocked.
 *      - Tighten-only: CF is restored by a governance VIP that reads EBrake.getMarketCFSnapshot() and then
 *        calls EBrake.resetCFSnapshot().
 *      - handleBStockPause is called by trusted keepers; EBrake makes repeat calls no-ops.
 */
contract BStockPauseSentinel is AccessControlledV8 {
    using EnumerableSetUpgradeable for EnumerableSetUpgradeable.AddressSet;

    /// @notice Emergency Brake contract used to zero the collateral factor
    /// @custom:oz-upgrades-unsafe-allow state-variable-immutable
    IEBrake public immutable EBRAKE;

    /// @notice Whether a keeper is trusted to call handleBStockPause
    mapping(address => bool) public trustedKeepers;

    /// @dev The monitored vToken markets, i.e. the markets handleBStockPause may zero the CF of
    EnumerableSetUpgradeable.AddressSet private monitoredMarkets;

    /// @dev Storage gap for future upgrades
    uint256[47] private __gap;

    /// @notice Emitted when a keeper's trusted status is updated
    /// @param keeper The keeper address
    /// @param isTrusted Whether the keeper is trusted
    event TrustedKeeperUpdated(address indexed keeper, bool isTrusted);

    /// @notice Emitted when a market is added to or removed from the monitored markets
    /// @param market The vToken market address
    /// @param monitored True if the market was added, false if it was removed
    event MarketMonitoringUpdated(address indexed market, bool monitored);

    /// @notice Emitted when handleBStockPause asks EBrake to zero the CF of a market whose underlying token is paused
    ///         or blocked for the market by the token's compliance module
    /// @dev Emitted on every handleBStockPause call that finds the token paused, including repeat calls on a
    ///      market whose CF is already zero (EBrake then makes no change and emits no CollateralFactorDecreased event)
    /// @param market The vToken market address
    /// @param underlying The paused underlying token
    /// @param pauseManager The PauseManager the underlying token points to
    event BStockPauseHandled(address indexed market, address indexed underlying, address pauseManager);

    /// @notice Thrown when a zero address is provided
    error ZeroAddress();

    /// @notice Thrown when handleBStockPause is called by an address that is not a trusted keeper
    error UnauthorizedKeeper();

    /// @notice Thrown when braking a market whose underlying token has no PauseManager
    /// @param market The vToken market address
    error MarketNotSupported(address market);

    /// @notice Thrown when handleBStockPause is called for a market that is not monitored
    /// @param market The vToken market address
    error MarketNotMonitored(address market);

    /// @notice Restricts a function to trusted keepers
    modifier onlyKeeper() {
        if (!trustedKeepers[msg.sender]) revert UnauthorizedKeeper();
        _;
    }

    /**
     * @notice Sets EBrake and disables initializers on the implementation
     * @param eBrake_ Address of the EBrake contract
     * @custom:error ZeroAddress if eBrake_ is the zero address
     * @custom:oz-upgrades-unsafe-allow constructor
     */
    constructor(IEBrake eBrake_) {
        if (address(eBrake_) == address(0)) revert ZeroAddress();
        EBRAKE = eBrake_;
        _disableInitializers();
    }

    /**
     * @notice Initializes the proxy with the AccessControlManager
     * @param accessControlManager_ Address of the AccessControlManager
     */
    function initialize(address accessControlManager_) external initializer {
        __AccessControlled_init(accessControlManager_);
    }

    /**
     * @notice Set the trusted status of a keeper allowed to call handleBStockPause
     * @param keeper The keeper address
     * @param isTrusted Whether the keeper should be trusted
     * @custom:access Controlled by AccessControlManager
     * @custom:event Emits TrustedKeeperUpdated
     * @custom:error ZeroAddress if keeper is the zero address
     */
    function setTrustedKeeper(address keeper, bool isTrusted) external {
        _checkAccessAllowed("setTrustedKeeper(address,bool)");

        if (keeper == address(0)) revert ZeroAddress();

        trustedKeepers[keeper] = isTrusted;
        emit TrustedKeeperUpdated(keeper, isTrusted);
    }

    /**
     * @notice Add a market to, or remove it from, the monitored markets
     * @dev The market is not checked here: EBrake checks its listing when it zeroes CF, and handleBStockPause
     *      checks its token.
     * @param market The vToken market address
     * @param monitored True to add the market, false to remove it
     * @custom:access Controlled by AccessControlManager
     * @custom:event Emits MarketMonitoringUpdated
     * @custom:error ZeroAddress if market is the zero address
     */
    function setMarketMonitored(address market, bool monitored) external {
        _checkAccessAllowed("setMarketMonitored(address,bool)");

        if (market == address(0)) revert ZeroAddress();

        if (monitored) {
            monitoredMarkets.add(market);
        } else {
            monitoredMarkets.remove(market);
        }
        emit MarketMonitoringUpdated(market, monitored);
    }

    /**
     * @notice Zero the collateral factor of a monitored market while its underlying token is paused, or blocked
     *         for the market by the token's compliance module
     * @dev Calls EBrake.decreaseCF(market, 0), which zeroes CF in the market's pool (on the BSC Core pool, also
     *      in every e-mode pool the market is listed in), keeps LT and snapshots the previous CF/LT. Repeat calls
     *      are no-ops in EBrake. The pause is read through checkBStockPause; while the token is not paused the
     *      call does nothing.
     *      Reverts if the underlying token does not expose pauseManager() or compliance().
     * @param market The vToken market address
     * @custom:access Only trusted keepers
     * @custom:event Emits BStockPauseHandled when the token is paused
     * @custom:error UnauthorizedKeeper if the caller is not a trusted keeper
     * @custom:error MarketNotMonitored if the market is not monitored
     * @custom:error MarketNotSupported if the underlying token has no PauseManager
     */
    function handleBStockPause(address market) external onlyKeeper {
        if (!isMarketMonitored(market)) revert MarketNotMonitored(market);

        (bool isPaused, address underlying, address pauseManager) = checkBStockPause(market);
        if (pauseManager == address(0)) revert MarketNotSupported(market);
        if (!isPaused) return;

        EBRAKE.decreaseCF(market, 0);

        emit BStockPauseHandled(market, underlying, pauseManager);
    }

    /**
     * @notice The monitored vToken markets
     * @return The monitored market addresses, in no particular order
     */
    function getMonitoredMarkets() external view returns (address[] memory) {
        return monitoredMarkets.values();
    }

    /**
     * @notice Check whether a monitored market's underlying bStock is paused, i.e. whether handleBStockPause would
     *         act on it
     * @dev Returns zeros for a market that is not monitored, and isPaused = false for an underlying token with
     *      no PauseManager. Reads the PauseManager the token itself points to. While the token is not paused, also
     *      reads the compliance module the token points to; a revert there counts as blocked (fail closed).
     *      Reverts if the underlying token does not expose pauseManager() or compliance().
     * @param market The vToken market address
     * @return isPaused True if the market is monitored and its underlying token is paused, or the token's
     *         compliance module sanctions the market or blocklists it for the token
     * @return underlying The market's underlying token, or address(0) if the market is not monitored
     * @return pauseManager The PauseManager the token points to, or address(0) if the market is not monitored or
     *         the token has none
     */
    function checkBStockPause(
        address market
    ) public view returns (bool isPaused, address underlying, address pauseManager) {
        if (!isMarketMonitored(market)) return (false, address(0), address(0));

        underlying = IVToken(market).underlying();
        if (underlying == address(0)) return (false, address(0), address(0));

        pauseManager = IBStockToken(underlying).pauseManager();
        if (pauseManager == address(0)) return (false, underlying, address(0));

        isPaused =
            IPauseManager(pauseManager).isTokenPaused(underlying) ||
            _isBlockedByCompliance(underlying, market);
    }

    /**
     * @dev True if the token's compliance module sanctions `market` or blocklists it for `underlying`. A reverting
     *      compliance call counts as blocked. A token without a compliance module blocks nothing.
     */
    function _isBlockedByCompliance(address underlying, address market) internal view returns (bool) {
        address compliance = IBStockToken(underlying).compliance();
        // A call to an address without code fails while decoding, which try/catch does not catch
        if (compliance == address(0)) return false;

        try ICompliance(compliance).sanctionedAddresses(market) returns (bool sanctioned) {
            if (sanctioned) return true;
        } catch {
            return true;
        }
        try ICompliance(compliance).blockedAddresses(underlying, market) returns (bool blocked) {
            return blocked;
        } catch {
            return true;
        }
    }

    /**
     * @notice Whether a vToken market is monitored, i.e. handleBStockPause may zero its CF
     * @param market The vToken market address
     * @return True if the market is monitored
     */
    function isMarketMonitored(address market) public view returns (bool) {
        return monitoredMarkets.contains(market);
    }
}

contracts/Sentinels/DeviationSentinel.so.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

import { IVToken } from "../Interfaces/IVToken.sol";
import { IEBrake } from "../EmergencyBrake/IEBrake.sol";
import {
    ResilientOracleInterface,
    OracleInterface
} from "@venusprotocol/oracle/contracts/interfaces/OracleInterface.sol";
import { AccessControlledV8 } from "@venusprotocol/governance-contracts/contracts/Governance/AccessControlledV8.sol";

/**
 * @title DeviationSentinel
 * @author Venus
 * @notice Sentinel that compares ResilientOracle and SentinelOracle prices (via keeper) and pauses
 *         specific actions (borrow, mint, collateral factor) per market when
 *         large deviations are detected. All emergency actions are routed through the EBrake contract.
 * @dev This contract can only TIGHTEN restrictions (pause, zero CF), never loosen them.
 *      Recovery (unpausing, restoring CF) is handled via governance VIP.
 *      CF tightening is performed by calling EBrake.decreaseCF(market, 0) — the most aggressive
 *      sentinel response — which zeros the collateral factor.
 *      Idempotency is handled by EBrake — duplicate calls are no-ops.
 */
contract DeviationSentinel is AccessControlledV8 {
    /// @notice Configuration for price deviation monitoring
    /// @param deviation Maximum allowed deviation percentage (e.g., 10 = 10%)
    /// @param enabled Whether deviation monitoring is enabled for this token
    struct DeviationConfig {
        uint8 deviation;
        bool enabled;
    }

    /// @notice Action taken by the sentinel when handling a deviation
    /// @param BorrowPaused Borrow was paused (sentinel price > oracle price)
    /// @param SupplyPausedAndCFZeroed CF was zeroed and supply was paused (sentinel price <= oracle price)
    enum DeviationAction {
        BorrowPaused,
        SupplyPausedAndCFZeroed
    }

    /// @notice Maximum allowed price deviation in percentage (e.g., 10 = 10%)
    uint8 public constant MAX_DEVIATION = 100;

    /// @notice Emergency Brake contract for executing pause and CF-zero actions
    /// @custom:oz-upgrades-unsafe-allow state-variable-immutable
    IEBrake public immutable EBRAKE;

    /// @notice Resilient Oracle for getting reference prices
    /// @custom:oz-upgrades-unsafe-allow state-variable-immutable
    ResilientOracleInterface public immutable RESILIENT_ORACLE;

    /// @notice Sentinel Oracle for getting DEX prices
    /// @custom:oz-upgrades-unsafe-allow state-variable-immutable
    OracleInterface public immutable SENTINEL_ORACLE;

    /// @notice Mapping of token addresses to their DEX configuration
    mapping(address => DeviationConfig) public tokenConfigs;

    /// @notice Mapping of trusted keeper addresses
    mapping(address => bool) public trustedKeepers;

    /// @dev Storage gap for future upgrades.
    uint256[48] private __gap;

    /// @notice Emitted when a token's deviation configuration is updated
    /// @param token The token address
    /// @param config The new deviation configuration
    event TokenConfigUpdated(address indexed token, DeviationConfig config);

    /// @notice Emitted when a token's monitoring status is changed
    /// @param token The token address
    /// @param enabled Whether monitoring is enabled
    event TokenMonitoringStatusChanged(address indexed token, bool enabled);

    /// @notice Emitted when a keeper's trusted status is updated
    /// @param keeper The keeper address
    /// @param isTrusted Whether the keeper is trusted
    event TrustedKeeperUpdated(address indexed keeper, bool isTrusted);

    /// @notice Emitted when a price deviation is detected and handled for a market
    /// @param market The market address
    /// @param oraclePrice The price from the resilient oracle at the time of detection
    /// @param sentinelPrice The price from the sentinel oracle at the time of detection
    /// @param action The action taken in response to the deviation
    event DeviationHandled(address indexed market, uint256 oraclePrice, uint256 sentinelPrice, DeviationAction action);

    /// @notice Thrown when deviation is set to zero
    error ZeroDeviation();

    /// @notice Thrown when deviation exceeds maximum allowed
    error ExceedsMaxDeviation();

    /// @notice Thrown when a zero address is provided
    error ZeroAddress();

    /// @notice Thrown when caller is not an authorized keeper
    error UnauthorizedKeeper();

    /// @notice Thrown when market is not configured for monitoring
    error MarketNotConfigured();

    /// @notice Thrown when token monitoring is disabled
    error TokenMonitoringDisabled();

    modifier onlyKeeper() {
        if (!trustedKeepers[msg.sender]) revert UnauthorizedKeeper();
        _;
    }

    /// @notice Constructor for DeviationSentinel
    /// @param eBrake_ Address of the EBrake contract
    /// @param resilientOracle_ Address of the resilient oracle
    /// @param sentinelOracle_ Address of the sentinel oracle
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(IEBrake eBrake_, ResilientOracleInterface resilientOracle_, OracleInterface sentinelOracle_) {
        if (address(eBrake_) == address(0)) revert ZeroAddress();
        if (address(resilientOracle_) == address(0)) revert ZeroAddress();
        if (address(sentinelOracle_) == address(0)) revert ZeroAddress();

        EBRAKE = eBrake_;
        RESILIENT_ORACLE = resilientOracle_;
        SENTINEL_ORACLE = sentinelOracle_;

        // Note that the contract is upgradeable. Use initialize() or reinitializers
        // to set the state variables.
        _disableInitializers();
    }

    /// @notice Initialize the contract
    /// @param accessControlManager_ Address of the access control manager
    function initialize(address accessControlManager_) external initializer {
        __AccessControlled_init(accessControlManager_);
    }

    /// @notice Set trusted status for a keeper
    /// @param keeper Address of the keeper
    /// @param isTrusted Whether the keeper should be trusted
    /// @custom:event Emits TrustedKeeperUpdated event
    /// @custom:error ZeroAddress is thrown when keeper address is zero
    function setTrustedKeeper(address keeper, bool isTrusted) external {
        _checkAccessAllowed("setTrustedKeeper(address,bool)");

        if (keeper == address(0)) revert ZeroAddress();

        trustedKeepers[keeper] = isTrusted;
        emit TrustedKeeperUpdated(keeper, isTrusted);
    }

    /// @notice Set deviation configuration for a token
    /// @param token Address of the token
    /// @param config Deviation configuration containing threshold and enabled status
    /// @custom:event Emits TokenConfigUpdated event
    /// @custom:error ZeroAddress is thrown when token address is zero
    /// @custom:error ZeroDeviation is thrown when deviation is set to zero
    /// @custom:error ExceedsMaxDeviation is thrown when deviation exceeds MAX_DEVIATION
    function setTokenConfig(address token, DeviationConfig calldata config) external {
        _checkAccessAllowed("setTokenConfig(address,(uint8,bool))");

        if (token == address(0)) revert ZeroAddress();
        if (config.deviation == 0) revert ZeroDeviation();
        if (config.deviation > MAX_DEVIATION) revert ExceedsMaxDeviation();

        tokenConfigs[token] = config;
        emit TokenConfigUpdated(token, config);
    }

    /// @notice Enable or disable deviation monitoring for a token
    /// @param token Address of the token
    /// @param enabled Whether to enable or disable monitoring
    /// @custom:event Emits TokenMonitoringStatusChanged event
    /// @custom:error ZeroAddress is thrown when token address is zero
    /// @custom:error MarketNotConfigured is thrown when token has no deviation config
    function setTokenMonitoringEnabled(address token, bool enabled) external {
        _checkAccessAllowed("setTokenMonitoringEnabled(address,bool)");

        if (token == address(0)) revert ZeroAddress();

        DeviationConfig storage config = tokenConfigs[token];
        if (config.deviation == 0) revert MarketNotConfigured();

        config.enabled = enabled;
        emit TokenMonitoringStatusChanged(token, enabled);
    }

    /// @notice Handle price deviation for a market by pausing borrow or zeroing CF and pausing supply
    /// @dev This contract can only tighten restrictions. Recovery (unpausing, restoring CF) is via governance VIP.
    /// @param market The vToken market to handle
    /// @custom:event Emits DeviationHandled with price context and the action taken
    /// @custom:error UnauthorizedKeeper is thrown when caller is not a trusted keeper
    /// @custom:error MarketNotConfigured is thrown when market's underlying token has no deviation config
    /// @custom:error TokenMonitoringDisabled is thrown when monitoring is disabled for the token
    function handleDeviation(IVToken market) external onlyKeeper {
        address underlyingToken = market.underlying();
        DeviationConfig memory config = tokenConfigs[underlyingToken];

        if (config.deviation == 0) revert MarketNotConfigured();
        if (!config.enabled) revert TokenMonitoringDisabled();

        (bool hasDeviation, uint256 oraclePrice, uint256 sentinelPrice, ) = checkPriceDeviation(market);

        if (!hasDeviation) return;

        DeviationAction action;
        if (sentinelPrice > oraclePrice) {
            EBRAKE.pauseBorrow(address(market));
            action = DeviationAction.BorrowPaused;
        } else {
            EBRAKE.decreaseCF(address(market), 0);
            EBRAKE.pauseSupply(address(market));
            action = DeviationAction.SupplyPausedAndCFZeroed;
        }
        emit DeviationHandled(address(market), oraclePrice, sentinelPrice, action);
    }

    /// @notice Check if there is a price deviation between resilient oracle and sentinel oracle for a market
    /// @param market The vToken market to check
    /// @return hasDeviation True if deviation exceeds configured threshold
    /// @return oraclePrice The price from resilient oracle
    /// @return sentinelPrice The price from sentinel oracle
    /// @return deviationPercent The percentage deviation (scaled by 100)
    function checkPriceDeviation(
        IVToken market
    ) public view returns (bool hasDeviation, uint256 oraclePrice, uint256 sentinelPrice, uint256 deviationPercent) {
        address underlyingToken = market.underlying();
        DeviationConfig memory config = tokenConfigs[underlyingToken];

        if (config.deviation == 0 || !config.enabled) return (false, 0, 0, 0);

        oraclePrice = RESILIENT_ORACLE.getPrice(underlyingToken);
        sentinelPrice = SENTINEL_ORACLE.getPrice(underlyingToken);

        if (oraclePrice == 0 || sentinelPrice == 0) {
            hasDeviation = true;
            deviationPercent = type(uint256).max;
            return (hasDeviation, oraclePrice, sentinelPrice, deviationPercent);
        }

        // Both prices are already in (36 - tokenDecimals) format, so we can compare directly
        uint256 priceDiff;
        if (sentinelPrice > oraclePrice) {
            priceDiff = sentinelPrice - oraclePrice;
        } else {
            priceDiff = oraclePrice - sentinelPrice;
        }

        deviationPercent = (priceDiff * 100) / oraclePrice;
        hasDeviation = deviationPercent >= config.deviation;
    }
}

contracts/Sentinels/HubNavDeviationSenti.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

import { IEBrake } from "../EmergencyBrake/IEBrake.sol";
import { IHub, IHubRegistry, IYieldGroupNav } from "../Interfaces/IHubLiquidity.sol";
import { AccessControlledV8 } from "@venusprotocol/governance-contracts/contracts/Governance/AccessControlledV8.sol";

/**
 * @title HubNavDeviationSentinel
 * @author Venus
 * @notice Sentinel a keeper drives to watch a Liquidity Hub resource's NavGuard band. When the reported
 *         value sits too far from the band's centre it pauses the whole Hub, which stops every deposit
 *         and redemption on it. It acts through EBrake.
 * @dev This contract can only TIGHTEN restrictions (pause), never loosen them.
 *      Recovery (unpausing) is handled via governance VIP.
 *      Idempotency is handled by EBrake — duplicate calls are no-ops.
 *
 *      The monitoring here stands on its own: it reads the band and judges the value against its own
 *      thresholds, whether or not the Hub is clamping that resource. Those thresholds should be set
 *      wider than the Hub's own gap, so routine clamping alone never trips a pause.
 */
contract HubNavDeviationSentinel is AccessControlledV8 {
    /// @notice Pause thresholds for one Liquidity Hub resource's NavGuard band
    /// @dev A zero threshold leaves that side unwatched, so a resource can be guarded one way only.
    /// @param hub The Hub to pause, read off the YieldGroup when configured and never from a keeper
    /// @param pauseUpBps How far above the band's centre the value must sit to trip, in bps of the anchor
    /// @param pauseDownBps How far below the band's centre the value must sit to trip, in bps of the anchor
    /// @param enabled Whether this band is being watched. Only `setNavMonitoringEnabled` writes it.
    /// @param minPauseGap Smallest gap from the centre that can pause the Hub, in asset units
    struct NavGuardConfig {
        address hub;
        uint16 pauseUpBps;
        uint16 pauseDownBps;
        bool enabled;
        uint256 minPauseGap;
    }

    /// @notice Why a NavGuard check did or did not call for a pause
    /// @dev Ordered so the zero value is a no-action one: an unwritten status reads as MonitoringDisabled.
    /// @param MonitoringDisabled This YieldGroup/resource pair is not armed in `navGuardConfigs`
    /// @param YieldGroupNotRegistered The Hub does not list the supplied YieldGroup
    /// @param ResourceNotRegistered The YieldGroup does not list the supplied resource
    /// @param ObservedValueZero The value source read back zero, but nothing is worth pausing for
    /// @param CentreZero The band is closed, but nothing is worth pausing for — see `checkNavGuardDeviation`
    /// @param WithinThreshold Not past either threshold, or past one by a gap no larger than `minPauseGap`
    /// @param Breached A pause is due: the value is past a threshold or reads zero, or a closed band is
    ///        valuing a live position at zero, and the gap is over `minPauseGap`
    enum NavGuardCheckStatus {
        MonitoringDisabled,
        YieldGroupNotRegistered,
        ResourceNotRegistered,
        ObservedValueZero,
        CentreZero,
        WithinThreshold,
        Breached
    }

    /// @notice Basis-point denominator, and the ceiling on either pause threshold
    /// @dev `pauseDownBps` must stay strictly below it: at 10_000 the downside trip point is the centre
    ///      less the whole anchor, 0 whenever the two are equal, and nothing is below 0, so that side
    ///      would never fire. Upward has no such point.
    uint16 public constant MAX_DEVIATION_BPS = 10_000;

    /// @notice Emergency Brake contract the Hub pause is routed through
    /// @custom:oz-upgrades-unsafe-allow state-variable-immutable
    IEBrake public immutable EBRAKE;

    /// @notice Chain-level Liquidity Hub directory, used to vouch for a YieldGroup's Hub at config time
    /// @custom:oz-upgrades-unsafe-allow state-variable-immutable
    IHubRegistry public immutable HUB_REGISTRY;

    /// @notice Mapping of trusted keeper addresses
    mapping(address => bool) public trustedKeepers;

    /// @notice NavGuard pause thresholds
    /// @dev Keyed on the pair because the band lives in each YieldGroup's own storage, so the same
    ///      resource under two YieldGroups has two independent bands.
    mapping(address yieldGroup => mapping(address resource => NavGuardConfig config)) public navGuardConfigs;

    /// @dev Storage gap for future upgrades.
    uint256[48] private __gap;

    /// @notice Emitted when a keeper's trusted status is updated
    /// @param keeper The keeper address
    /// @param isTrusted Whether the keeper is trusted
    event TrustedKeeperUpdated(address indexed keeper, bool isTrusted);

    /// @notice Emitted when a resource's NavGuard pause thresholds are updated
    /// @param hub The Liquidity Hub the YieldGroup belongs to
    /// @param yieldGroup The YieldGroup holding the resource
    /// @param resource The Liquidity Hub resource address
    /// @param config The stored config after the update
    event NavGuardConfigUpdated(
        address indexed hub,
        address indexed yieldGroup,
        address indexed resource,
        NavGuardConfig config
    );

    /// @notice Emitted when a resource's band starts or stops being watched
    /// @param hub The Liquidity Hub the YieldGroup belongs to
    /// @param yieldGroup The YieldGroup holding the resource
    /// @param resource The Liquidity Hub resource address
    /// @param enabled Whether the band is being watched
    event NavGuardStatusChanged(
        address indexed hub,
        address indexed yieldGroup,
        address indexed resource,
        bool enabled
    );

    /// @notice Emitted when a resource breaks through its NavGuard band and the Hub is paused
    /// @dev `centre` is what the breach was measured against, and the two bounds are the band the
    ///      Hub was applying at the time, all three with drift included. An operator can recompute
    ///      the ordinary trip point from the thresholds and the band's anchor — except when `centre`
    ///      or `observedValue` is 0, where the breach is a closed band holding a real value or an open
    ///      band reading zero, not a percentage miss.
    /// @param hub The Liquidity Hub that was paused
    /// @param yieldGroup The YieldGroup holding the breaching resource
    /// @param resource The resource whose value broke through its band
    /// @param observedValue Value the counterparty reported at detection time
    /// @param centre What the band says the position is worth, which the thresholds measure from
    /// @param minAllowedValue The band's floor at detection time
    /// @param maxAllowedValue The band's cap at detection time
    event NavGuardDeviationHandled(
        address indexed hub,
        address indexed yieldGroup,
        address indexed resource,
        uint256 observedValue,
        uint256 centre,
        uint256 minAllowedValue,
        uint256 maxAllowedValue
    );

    /// @notice Thrown when both thresholds are set to zero
    error ZeroDeviation();

    /// @notice Thrown when `minPauseGap` is zero
    error ZeroMinPauseGap();

    /// @notice Thrown when a threshold is out of range
    error ExceedsMaxDeviation();

    /// @notice Thrown when a zero address is provided
    error ZeroAddress();

    /// @notice Thrown when caller is not an authorized keeper
    error UnauthorizedKeeper();

    /// @notice Thrown when a resource has no NavGuard pause thresholds set
    error ResourceNotConfigured(address yieldGroup, address resource);

    /// @notice Thrown when a resource's NavGuard band is not being watched
    error NavGuardDisabled(address yieldGroup, address resource);

    /// @notice Thrown when the YieldGroup's Hub is not one the registry lists
    error HubNotRegistered(address hub, address yieldGroup);

    /// @notice Thrown when the Hub does not list the supplied YieldGroup in its registry
    error YieldGroupNotRegistered(address hub, address yieldGroup);

    /// @notice Thrown when the YieldGroup does not list the supplied resource in its registry
    /// @dev Unregistered means zero balance, so it is outside `totalAssets()` and nothing to pause.
    error ResourceNotRegistered(address yieldGroup, address resource);

    /// @notice Thrown when the value reads zero but nothing is worth pausing for
    /// @dev A failed read and a position priced at nothing both arrive as zero. Either one pauses
    ///      on an open band; this fires only when the band is closed, the downside is unwatched, or
    ///      the centre is within `minPauseGap`.
    error NavGuardObservedValueZero(address resource);

    /// @notice Thrown when the band is closed but nothing here is mis-valued enough to pause for
    /// @dev The same closed band with the cap armed, the downside watched and more than
    ///      `minPauseGap` left in it is a `Breached` pause instead — see `checkNavGuardDeviation`.
    error NavGuardCentreZero(address resource);

    /// @notice Thrown when the value is not past a pause threshold, or is past one by a gap no larger
    ///         than `minPauseGap`
    /// @dev Small enough to let the band step down on its own.
    error DeviationWithinThreshold(address resource, uint256 observedValue);

    modifier onlyKeeper() {
        if (!trustedKeepers[msg.sender]) revert UnauthorizedKeeper();
        _;
    }

    /// @notice Constructor for HubNavDeviationSentinel
    /// @param eBrake_ Address of the EBrake contract
    /// @param hubRegistry_ Address of the Liquidity Hub registry
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(IEBrake eBrake_, IHubRegistry hubRegistry_) {
        if (address(eBrake_) == address(0)) revert ZeroAddress();
        if (address(hubRegistry_) == address(0)) revert ZeroAddress();

        EBRAKE = eBrake_;
        HUB_REGISTRY = hubRegistry_;

        // Note that the contract is upgradeable. Use initialize() or reinitializers
        // to set the state variables.
        _disableInitializers();
    }

    /// @notice Initialize the contract
    /// @param accessControlManager_ Address of the access control manager
    function initialize(address accessControlManager_) external initializer {
        __AccessControlled_init(accessControlManager_);
    }

    /// @notice Set trusted status for a keeper
    /// @param keeper Address of the keeper
    /// @param isTrusted Whether the keeper should be trusted
    /// @custom:event Emits TrustedKeeperUpdated event
    /// @custom:error ZeroAddress is thrown when keeper address is zero
    function setTrustedKeeper(address keeper, bool isTrusted) external {
        _checkAccessAllowed("setTrustedKeeper(address,bool)");

        if (keeper == address(0)) revert ZeroAddress();

        trustedKeepers[keeper] = isTrusted;
        emit TrustedKeeperUpdated(keeper, isTrusted);
    }

    /// @notice Set the NavGuard pause thresholds for a Liquidity Hub resource
    /// @dev Thresholds and min pause gap only: arming is `setNavMonitoringEnabled`, so retuning one cannot arm or disarm
    ///      it. Both are measured from the band's centre, so each has to exceed the Hub's matching
    ///      gap, `upGapBps` or `downGapBps`, or clamping the Hub does routinely trips a pause.
    /// @param yieldGroup Address of the YieldGroup holding the resource
    /// @param resource Address of the resource inside that YieldGroup
    /// @param pauseUpBps How far above the centre the value must sit to trip, in bps of the anchor; zero leaves it unwatched
    /// @param pauseDownBps How far below the centre the value must sit to trip, in bps of the anchor; zero leaves it unwatched
    /// @param minPauseGap Smallest gap from the centre that can pause the Hub, in asset units; must be over zero
    /// @custom:access Controlled by AccessControlManager
    /// @custom:event Emits NavGuardConfigUpdated event
    /// @custom:error ZeroAddress is thrown when the YieldGroup or resource address is zero
    /// @custom:error ZeroDeviation is thrown when both thresholds are zero
    /// @custom:error ZeroMinPauseGap is thrown when the minimum pause gap is zero
    /// @custom:error ExceedsMaxDeviation is thrown when a threshold is out of range
    /// @custom:error HubNotRegistered is thrown when the registry does not list the YieldGroup's Hub
    /// @custom:error YieldGroupNotRegistered is thrown when that Hub does not list the YieldGroup
    /// @custom:error ResourceNotRegistered is thrown when the YieldGroup does not list the resource
    function setHubNavConfig(
        address yieldGroup,
        address resource,
        uint16 pauseUpBps,
        uint16 pauseDownBps,
        uint256 minPauseGap
    ) external {
        _checkAccessAllowed("setHubNavConfig(address,address,uint16,uint16,uint256)");

        if (yieldGroup == address(0) || resource == address(0)) revert ZeroAddress();
        if (pauseUpBps == 0 && pauseDownBps == 0) revert ZeroDeviation();
        if (pauseUpBps > MAX_DEVIATION_BPS || pauseDownBps >= MAX_DEVIATION_BPS) revert ExceedsMaxDeviation();
        // The band's anchor is 0 from a resource's first deposit until its first re-anchor, which
        // puts both trip points on the centre. The centre drifts while a pending deposit is counted
        // at face, so this minimum is all that keeps that routine gap from pausing the Hub.
        if (minPauseGap == 0) revert ZeroMinPauseGap();

        address hub = _requireLiveResource(yieldGroup, resource);

        NavGuardConfig storage config = navGuardConfigs[yieldGroup][resource];
        config.pauseUpBps = pauseUpBps;
        config.pauseDownBps = pauseDownBps;
        config.minPauseGap = minPauseGap;
        config.hub = hub;

        emit NavGuardConfigUpdated(hub, yieldGroup, resource, config);
    }

    /// @notice Start or stop watching a resource's NavGuard band, keeping its thresholds
    /// @dev Arming re-runs the checks `setHubNavConfig` ran, since a Hub or a resource can be
    ///      de-registered in between. Disarming runs none, so a dropped pair can always be turned off.
    /// @param yieldGroup Address of the YieldGroup holding the resource
    /// @param resource Address of the resource
    /// @param enabled Whether to watch this resource's band
    /// @custom:event Emits NavGuardStatusChanged event
    /// @custom:error ZeroAddress is thrown when the YieldGroup or resource address is zero
    /// @custom:error ResourceNotConfigured is thrown when the pair has no thresholds set
    /// @custom:error HubNotRegistered is thrown when arming and the registry has dropped the Hub
    /// @custom:error YieldGroupNotRegistered is thrown when arming and the Hub has dropped the YieldGroup
    /// @custom:error ResourceNotRegistered is thrown when arming and the YieldGroup has dropped the resource
    function setNavMonitoringEnabled(address yieldGroup, address resource, bool enabled) external {
        _checkAccessAllowed("setNavMonitoringEnabled(address,address,bool)");

        if (yieldGroup == address(0) || resource == address(0)) revert ZeroAddress();

        NavGuardConfig storage config = navGuardConfigs[yieldGroup][resource];
        if (config.pauseUpBps == 0 && config.pauseDownBps == 0) revert ResourceNotConfigured(yieldGroup, resource);

        if (enabled) config.hub = _requireLiveResource(yieldGroup, resource);

        config.enabled = enabled;
        emit NavGuardStatusChanged(config.hub, yieldGroup, resource, enabled);
    }

    /// @notice Handle a NavGuard band breach on a Liquidity Hub resource by pausing the Hub
    /// @dev The whole Hub is paused, not the breaching resource: `YieldGroupBase.totalAssets()` sums
    ///      every registered resource without reading its pause flag, so pausing just that resource
    ///      would leave the same wrong number priced into deposits and redemptions.
    /// @param yieldGroup The YieldGroup holding the resource. Checked against its Hub's registry.
    /// @param resource The resource whose NavGuard band to read
    /// @custom:event Emits NavGuardDeviationHandled with the band context at detection time
    /// @custom:error UnauthorizedKeeper is thrown when caller is not a trusted keeper
    /// @custom:error NavGuardDisabled (pair not watched), YieldGroupNotRegistered (Hub dropped the
    ///        YieldGroup), ResourceNotRegistered (YieldGroup dropped the resource),
    ///        NavGuardObservedValueZero (value source reads zero), NavGuardCentreZero (band closed
    ///        with nothing worth pausing for), or DeviationWithinThreshold (break below the
    ///        threshold, or under `minPauseGap`) — each is one non-breach status
    ///        `checkNavGuardDeviation` can return.
    function handleNavGuardDeviation(address yieldGroup, address resource) external onlyKeeper {
        (
            NavGuardCheckStatus status,
            address hub,
            uint256 observedValue,
            uint256 centre,
            uint256 minAllowedValue,
            uint256 maxAllowedValue
        ) = checkNavGuardDeviation(yieldGroup, resource);

        if (status == NavGuardCheckStatus.MonitoringDisabled) revert NavGuardDisabled(yieldGroup, resource);
        if (status == NavGuardCheckStatus.YieldGroupNotRegistered) revert YieldGroupNotRegistered(hub, yieldGroup);
        if (status == NavGuardCheckStatus.ResourceNotRegistered) revert ResourceNotRegistered(yieldGroup, resource);
        if (status == NavGuardCheckStatus.ObservedValueZero) revert NavGuardObservedValueZero(resource);
        if (status == NavGuardCheckStatus.CentreZero) revert NavGuardCentreZero(resource);
        if (status == NavGuardCheckStatus.WithinThreshold) revert DeviationWithinThreshold(resource, observedValue);

        // Backstop for a status the list above does not name: fall through to doing nothing rather
        // than to pausing a Hub on a verdict this function was never taught to read.
        if (status != NavGuardCheckStatus.Breached) return;

        EBRAKE.pauseHub(hub);

        emit NavGuardDeviationHandled(
            hub,
            yieldGroup,
            resource,
            observedValue,
            centre,
            minAllowedValue,
            maxAllowedValue
        );
    }

    /// @notice Check whether a Liquidity Hub resource's NAV has broken through its NavGuard band by
    ///         more than the configured threshold, and why
    /// @dev `handleNavGuardDeviation` calls this rather than repeating the comparison, so what
    ///      monitoring reads and what the keeper acts on cannot drift apart.
    ///      Can revert: `yieldGroup` is caller-supplied, so a non-contract address or a revert
    ///      inside it propagates out.
    /// @param yieldGroup The YieldGroup holding the resource
    /// @param resource The resource whose NavGuard band to read
    /// @return status Why a pause is or is not due
    /// @return hub The Hub that would be paused, as governance configured it; `0` when unwatched
    /// @return observedValue Value the counterparty reports, in asset units; `0` if unread or empty
    /// @return centre What the band says the position is worth, drift included; `0` if unread or closed
    /// @return minAllowedValue The band's floor; `0` before it is read, or when the band is closed
    /// @return maxAllowedValue The band's cap; `0` before it is read, or when the band is closed
    function checkNavGuardDeviation(
        address yieldGroup,
        address resource
    )
        public
        view
        returns (
            NavGuardCheckStatus status,
            address hub,
            uint256 observedValue,
            uint256 centre,
            uint256 minAllowedValue,
            uint256 maxAllowedValue
        )
    {
        NavGuardConfig memory config = navGuardConfigs[yieldGroup][resource];
        if (!config.enabled) return (NavGuardCheckStatus.MonitoringDisabled, address(0), 0, 0, 0, 0);

        hub = config.hub;

        if (!IHub(hub).yieldGroupConfig(yieldGroup).registered) {
            return (NavGuardCheckStatus.YieldGroupNotRegistered, hub, 0, 0, 0, 0);
        }

        (bool registered, , ) = IYieldGroupNav(yieldGroup).resourceConfig(resource);
        if (!registered) return (NavGuardCheckStatus.ResourceNotRegistered, hub, 0, 0, 0, 0);

        (observedValue, minAllowedValue, maxAllowedValue, , ) = IYieldGroupNav(yieldGroup).navGuardStatus(resource);

        // Our pause thresholds are measured from the centre, not the Hub's min and max, because those
        // include the Hub's own gap and would shift our thresholds whenever that gap is changed.
        IYieldGroupNav.NavBand memory band = IYieldGroupNav(yieldGroup).navGuard(resource);

        // The centre and anchor grow by `driftBps` a year but are only saved on a deposit, redeem or re-anchor,
        // so add the growth since `driftFrom`, the same way the Hub's `NavGuard._grown` does.
        centre = _driftGrown(band.centre, band);
        uint256 anchor = _driftGrown(band.anchor, band);

        // Both zeros are handled here, since either puts a trip point at 0 and would pause on every
        // reading below. A zero `observedValue` is a full loss; a zero `centre` is a closed band.
        if (observedValue == 0) {
            // The whole centre is the gap, so `minPauseGap` still keeps a small position from pausing.
            bool zeroReadingBreached = centre != 0 && config.pauseDownBps != 0 && centre > config.minPauseGap;

            status = zeroReadingBreached ? NavGuardCheckStatus.Breached : NavGuardCheckStatus.ObservedValueZero;
            return (status, hub, observedValue, centre, minAllowedValue, maxAllowedValue);
        }
        if (centre == 0) {
            // The band is closed but the position still holds value. With the cap on, the Hub values
            // it at 0, so Hub NAV is short by `observedValue`. That is a pause when the downside is
            // watched, unless what is left is dust under `minPauseGap`.
            bool closedBandBreached = band.capEnabled && config.pauseDownBps != 0 && observedValue > config.minPauseGap;

            status = closedBandBreached ? NavGuardCheckStatus.Breached : NavGuardCheckStatus.CentreZero;
            return (status, hub, observedValue, centre, minAllowedValue, maxAllowedValue);
        }

        // Sized off the anchor, as the Hub sizes its gaps, so an inflow cannot widen them.
        uint256 downTripPoint = centre - (anchor * config.pauseDownBps) / MAX_DEVIATION_BPS;
        uint256 upTripPoint = centre + (anchor * config.pauseUpBps) / MAX_DEVIATION_BPS;

        // A threshold of 0 means that side is off, not that it pauses on any move.
        bool breachedDown = config.pauseDownBps != 0 && observedValue < downTripPoint;
        bool breachedUp = config.pauseUpBps != 0 && observedValue > upTripPoint;

        // Crossing a threshold is not enough: the gap must also be over `minPauseGap`, the same
        // test a closed band gets. The side that crossed puts `observedValue` above or below the
        // centre, so the subtraction cannot underflow.
        bool breached = (breachedDown || breachedUp) &&
            (breachedUp ? observedValue - centre : centre - observedValue) > config.minPauseGap;

        status = breached ? NavGuardCheckStatus.Breached : NavGuardCheckStatus.WithinThreshold;
    }

    /// @notice A band value grown by its drift since `driftFrom`
    /// @param value The stored centre or anchor
    /// @param band The band to read the drift from
    /// @return The drift-grown value
    function _driftGrown(uint256 value, IYieldGroupNav.NavBand memory band) private view returns (uint256) {
        return
            value +
            (value * band.driftBps * (block.timestamp - band.driftFrom)) / (uint256(MAX_DEVIATION_BPS) * 365 days);
    }

    /// @notice Resolve a YieldGroup's Hub and prove the whole chain down to the resource is live
    /// @dev Three reads, each covering what the one before cannot: the registry vouches for the
    ///      Hub, the Hub for the YieldGroup, and the YieldGroup for the resource.
    /// @param yieldGroup YieldGroup to resolve
    /// @param resource Resource that must belong to it
    /// @return hub The Hub that YieldGroup reports to
    function _requireLiveResource(address yieldGroup, address resource) private view returns (address hub) {
        hub = IYieldGroupNav(yieldGroup).hub();
        if (!HUB_REGISTRY.isHub(hub)) revert HubNotRegistered(hub, yieldGroup);
        if (!IHub(hub).yieldGroupConfig(yieldGroup).registered) revert YieldGroupNotRegistered(hub, yieldGroup);

        (bool registered, , ) = IYieldGroupNav(yieldGroup).resourceConfig(resource);
        if (!registered) revert ResourceNotRegistered(yieldGroup, resource);
    }
}

contracts/Sentinels/Oracles/AerodromeSli.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

import { IAerodromeSlipstreamPool } from "../../Interfaces/IAerodromeSlipstreamPool.sol";
import { ResilientOracleInterface } from "@venusprotocol/oracle/contracts/interfaces/OracleInterface.sol";
import { AccessControlledV8 } from "@venusprotocol/governance-contracts/contracts/Governance/AccessControlledV8.sol";
import { FixedPoint96 } from "../../Libraries/FixedPoint96.sol";
import { FullMath } from "../../Libraries/FullMath.sol";

/**
 * @title AerodromeSlipstreamOracle
 * @author Venus
 * @notice Oracle for fetching asset prices from Aerodrome Slipstream (CL) pools on Base.
 *
 * @dev Aerodrome Slipstream is a concentrated-liquidity AMM (Uniswap V3 fork).
 *      Its slot0() returns 6 values — no feeProtocol field — so it is incompatible
 *      with IUniswapV3Pool. The sqrtPriceX96 → price math is otherwise identical.
 *
 *      Uses the current slot0 price (not TWAP). Suitable for sentinel deviation
 *      detection where some manipulation tolerance is acceptable; for higher
 *      security, add observe()-based TWAP in a subclass.
 */
contract AerodromeSlipstreamOracle is AccessControlledV8 {
    /// @notice Resilient Oracle for getting reference token prices
    /// @custom:oz-upgrades-unsafe-allow state-variable-immutable
    ResilientOracleInterface public immutable RESILIENT_ORACLE;

    /// @notice Mapping of token addresses to their pool addresses
    mapping(address => address) public tokenPools;

    /// @notice Emitted when a token's pool configuration is updated
    event PoolConfigUpdated(address indexed token, address indexed pool);

    /// @notice Thrown when a zero address is provided
    error ZeroAddress();

    /// @notice Thrown when the token is not coins[0] or coins[1] of the configured pool
    error InvalidPool();

    /// @notice Thrown when token is not configured
    error TokenNotConfigured();

    /// @notice Constructor
    /// @param resilientOracle_ Address of the resilient oracle
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(ResilientOracleInterface resilientOracle_) {
        RESILIENT_ORACLE = resilientOracle_;
        _disableInitializers();
    }

    /// @notice Initialize the contract
    /// @param accessControlManager_ Address of the access control manager
    function initialize(address accessControlManager_) external initializer {
        __AccessControlled_init(accessControlManager_);
    }

    /// @notice Set pool configuration for a token
    /// @param token Address of the token
    /// @param pool Address of the Aerodrome Slipstream pool
    /// @custom:event Emits PoolConfigUpdated
    /// @custom:error ZeroAddress if token or pool is zero
    function setPoolConfig(address token, address pool) external {
        _checkAccessAllowed("setPoolConfig(address,address)");

        if (token == address(0) || pool == address(0)) revert ZeroAddress();

        tokenPools[token] = pool;
        emit PoolConfigUpdated(token, pool);
    }

    /// @notice Get the price of an asset from its configured Aerodrome Slipstream pool
    /// @param asset Address of the asset
    /// @return price Price in (36 - asset decimals) format, same as ResilientOracle
    /// @custom:error TokenNotConfigured if asset has no pool configured
    function getPrice(address asset) external view returns (uint256 price) {
        address pool = tokenPools[asset];
        if (pool == address(0)) revert TokenNotConfigured();

        return _getSlipstreamPrice(pool, asset);
    }

    function _getSlipstreamPrice(address pool, address token) internal view returns (uint256 price) {
        IAerodromeSlipstreamPool clPool = IAerodromeSlipstreamPool(pool);
        address token0 = clPool.token0();
        address token1 = clPool.token1();
        (uint160 sqrtPriceX96, , , , , ) = clPool.slot0();

        uint256 priceX96 = FullMath.mulDiv(sqrtPriceX96, sqrtPriceX96, FixedPoint96.Q96);

        address referenceToken;
        bool targetIsToken0;

        if (token == token0) {
            targetIsToken0 = true;
            referenceToken = token1;
        } else if (token == token1) {
            targetIsToken0 = false;
            referenceToken = token0;
        } else {
            revert InvalidPool();
        }

        uint256 referencePrice = RESILIENT_ORACLE.getPrice(referenceToken);

        if (targetIsToken0) {
            price = FullMath.mulDiv(referencePrice, priceX96, FixedPoint96.Q96);
        } else {
            price = FullMath.mulDiv(referencePrice, FixedPoint96.Q96, priceX96);
        }
    }
}

